using System.Security.Claims; using DigiMenu.Api.Data; using DigiMenu.Api.Domain; using Microsoft.EntityFrameworkCore;
namespace DigiMenu.Api.Services;
public interface IBusinessAccess { Guid UserId(ClaimsPrincipal user); bool IsSuperadmin(ClaimsPrincipal user); Task<Guid> CurrentBusinessId(ClaimsPrincipal user); Task EnsureAccess(ClaimsPrincipal user,Guid businessId); }
public class BusinessAccess(DigiMenuDbContext db, IHttpContextAccessor context):IBusinessAccess { public Guid UserId(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)??throw new UnauthorizedAccessException()); public bool IsSuperadmin(ClaimsPrincipal u)=>u.IsInRole(Role.Superadmin.ToString()); public async Task<Guid> CurrentBusinessId(ClaimsPrincipal u){var raw=u.FindFirstValue("BusinessID");if(Guid.TryParse(raw,out var id))return id;if(IsSuperadmin(u)&&Guid.TryParse(context.HttpContext?.Request.Headers["X-Business-ID"],out var selected)&&await db.Businesses.AnyAsync(x=>x.Id==selected&&x.IsActive))return selected;throw new UnauthorizedAccessException("BusinessID requerido. Un superadministrador debe enviar X-Business-ID.");} public async Task EnsureAccess(ClaimsPrincipal u,Guid businessId){if(IsSuperadmin(u))return;var uid=UserId(u);if(!await db.UserBusinesses.AnyAsync(x=>x.UserId==uid&&x.BusinessID==businessId&&x.IsActive))throw new UnauthorizedAccessException("No tiene acceso a este negocio.");} }
